import {investigate} from './mystery.js';
import {parseCSV, suggestMapping, normalizeData, summarize, filterPeriod, groupBy, percentChange, METRICS} from './analytics.js';

const $ = s => document.querySelector(s);
const content = $('#content'), dialog = $('#upload-dialog');
const state = {data:null, name:'', example:false, days:'30', parsed:null, page:'overview', question:'', search:'', metric:'revenue', sort:'revenue', mode:'personal', goal:'Sales', report:{}, plan:{}};
const slots={personal:null,demo:null};
const colors = ['#ff923d','#69b8f3','#ffc835','#e995a2','#9dc58e','#b99bdb'];
const escapeHTML = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = v => v === null || !Number.isFinite(v) ? '—' : new Intl.NumberFormat('en-US',{style:'currency',currency:state.data?.currency || 'USD',minimumFractionDigits:0,maximumFractionDigits:2}).format(v);
const count = v => v === null || !Number.isFinite(v) ? '—' : new Intl.NumberFormat('en-US',{maximumFractionDigits:1}).format(v);
const ratio = v => v === null || !Number.isFinite(v) ? '—' : `${v.toFixed(2)}x`;
const valueLabel = () => state.data?.valueKind==='conversion'?'Platform-reported conversion value':'Revenue';
const valueWord = () => state.data?.valueKind==='conversion'?'platform-reported conversion value':'revenue';
const metricText = (key,v) => ['conversions','clicks','impressions'].includes(key) ? count(v) : key === 'roas' ? ratio(v) : money(v);
const dateLabel = iso => iso ? new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'}).format(new Date(`${iso}T00:00:00Z`)) : '';
const compactDate = iso => new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',timeZone:'UTC'}).format(new Date(`${iso}T00:00:00Z`));
const getPage = () => ['overview','campaigns','channels','insights','ask','data','report','planner','guide','mystery'].includes(location.hash.slice(1)) ? location.hash.slice(1) : 'overview';
const currentPeriod = () => state.data ? filterPeriod(state.data.records,state.days) : {current:[], previous:[],start:null,end:null};
const complete = (summary,key) => summary.count > 0 && summary[`${key}Coverage`] === summary.count;
const comparable = period => state.days !== 'all' && new Set(period.current.map(r=>r.date)).size === Number(state.days) && new Set(period.previous.map(r=>r.date)).size === Number(state.days);
const priorSummary = period => summarize(comparable(period) ? period.previous : []);
const summaryChange = (cur,prev,key) => {
  if (!prev.count) return null;
  if (key === 'roas') return percentChange(cur.roas,prev.roas);
  return complete(cur,key) && complete(prev,key) ? percentChange(cur[key],prev[key]) : null;
};
function dateSelect(){return `<label class="select-wrap"><span class="sr-only">Date range</span><select id="period"><option value="30" ${state.days==='30'?'selected':''}>Last 30 days</option><option value="7" ${state.days==='7'?'selected':''}>Last 7 days</option><option value="90" ${state.days==='90'?'selected':''}>Last 90 days</option><option value="all" ${state.days==='all'?'selected':''}>All dates</option></select></label>`}
function metrics(cur,prev){
  const definitions={spend:'Sum of recorded spend.',revenue:`Sum of recorded ${valueWord()}.`,conversions:'Sum of recorded conversions.',roas:`Recorded ${valueWord()} divided by recorded spend; not profit.`};
  const items=[['spend','Spend','◒'],['revenue',valueLabel(),'▰'],['conversions','Conversions','●'],['roas','ROAS','▥']];
  return `<div class="metric-grid">${items.map(([key,label,icon])=>{
    const val=cur[key]??null, change=summaryChange(cur,prev,key);
    let note=!state.data?'Waiting for your CSV': val===null ? 'Not enough data' : key!=='roas'&&!complete(cur,key)?`Partial: ${cur[`${key}Coverage`]}/${cur.count} rows` : change===null?'No prior comparison':change===0?'Unchanged vs. prior period':`<span class="${change>0?'trend-up':'trend-down'}">${change>0?'▲':'▼'} ${Math.abs(change).toFixed(1)}%</span> vs. prior period`;
    return `<article class="metric-card"><div class="metric-icon" aria-hidden="true">${icon}</div><div class="metric-content"><div class="metric-name">${label} <span title="${definitions[key]}" aria-label="${definitions[key]}">ⓘ</span></div><div class="metric-value">${metricText(key,val)}</div><div class="metric-foot">${note}</div></div></article>`;
  }).join('')}</div>`;
}
function chart(rows){
  const key=state.metric; const revRows=rows.filter(r=>Number.isFinite(r[key]));
  if(!revRows.length) return `<div class="chart-empty"><span class="empty-star">✦</span><strong>${state.data?'No values to chart yet':'A little room for your big picture'}</strong><p>${state.data?'Choose a metric with recorded values to see your performance over time.':'Your chart and channel breakdown will appear once you add a CSV.'}</p></div>`;
  const channels=groupBy(rows,'channel').filter(g=>g[key]!==null).sort((a,b)=>(b[key]??-Infinity)-(a[key]??-Infinity)).slice(0,3); const dates=[...new Set(revRows.map(r=>r.date))].sort();
  const daily=new Map(); for(const r of revRows){const k=`${r.date}\u0000${r.channel}`;daily.set(k,(daily.get(k)||0)+r[key])}
  const values=[...daily.values()], min=Math.min(0,...values), max=Math.max(0,...values); const scale=(max-min)||1;
  const w=650,h=218,left=59,right=16,top=15,bottom=30;
  const minTime=Date.parse(`${dates[0]}T00:00:00Z`),maxTime=Date.parse(`${dates.at(-1)}T00:00:00Z`);
  const x=iso => dates.length===1 ? (left+w-right)/2 : left+(Date.parse(`${iso}T00:00:00Z`)-minTime)/(maxTime-minTime)*(w-left-right);
  const y=n=>top+(max-n)/scale*(h-top-bottom);
  let axes=''; for(let i=0;i<=4;i++){const yy=top+i*(h-top-bottom)/4, v=max-i*scale/4;axes+=`<line class="grid" x1="${left}" x2="${w-right}" y1="${yy}" y2="${yy}"/><text x="${left-8}" y="${yy+4}" text-anchor="end">${escapeHTML(metricText(key,v))}</text>`;}
  const ticks=[...new Set([dates[0],dates[Math.floor((dates.length-1)/2)],dates.at(-1)])];for(const d of ticks)axes+=`<text x="${x(d)}" y="${h-6}" text-anchor="middle">${escapeHTML(compactDate(d))}</text>`;
  const lines=channels.map((g,i)=>{const points=dates.filter(d=>daily.has(`${d}\u0000${g.label}`)).map(d=>[x(d),y(daily.get(`${d}\u0000${g.label}`)),d,daily.get(`${d}\u0000${g.label}`)]);if(!points.length)return '';const path=points.map(([xx,yy],n)=>`${n?'L':'M'}${xx.toFixed(1)} ${yy.toFixed(1)}`).join(' ');const markers=points.length<=180?points.map(([xx,yy,d,v])=>`<circle cx="${xx}" cy="${yy}" r="4" fill="${colors[i]}"><title>${escapeHTML(g.label)} · ${escapeHTML(dateLabel(d))}: ${escapeHTML(metricText(key,v))}</title></circle>`).join(''):'';return `<path class="series" stroke="${colors[i]}" d="${path}"/>${markers}`}).join('');
  return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${escapeHTML(key==='revenue'?valueWord():key)} by channel over recorded dates; recorded values are available in the chart table.">${axes}${lines}</svg><div class="legend">${channels.map((g,i)=>`<span><i class="legend-dot" style="background:${colors[i]}"></i>${escapeHTML(g.label)}</span>`).join('')}</div><p class="footnote">${escapeHTML(key==='revenue'?valueLabel():key[0].toUpperCase()+key.slice(1))} by channel, for recorded dates. Lines connect available points; missing dates aren't assumed to be zero. ${channels.length===3&&groupBy(rows,'channel').length>3?'Showing the top 3 channels for the selected metric.':''}</p><details class="chart-details"><summary>View recorded chart values</summary><div class="table-scroll"><table><thead><tr><th>Date</th>${channels.map(g=>`<th>${escapeHTML(g.label)}</th>`).join('')}</tr></thead><tbody>${dates.map(d=>`<tr><td>${escapeHTML(dateLabel(d))}</td>${channels.map(g=>`<td>${daily.has(`${d}\u0000${g.label}`)?metricText(key,daily.get(`${d}\u0000${g.label}`)):'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>`;
}
function channelTable(rows){
 const groups=groupBy(rows,'channel');
 if(!groups.length)return `<div class="table-box"><h3>Channel breakdown</h3><p class="footnote">Your channels will have a home here.</p></div>`;
 const total=groups.reduce((a,b)=>a+(b.revenue??0),0); const canShare=total>0&&groups.every(g=>g.revenue===null||g.revenue>=0);
 return `<div class="table-box"><h3>Channel breakdown</h3><div class="table-scroll"><table><thead><tr><th>Channel</th><th>Spend</th><th>${valueLabel()}</th><th>Conversions</th><th>ROAS</th><th>Share*</th></tr></thead><tbody>${groups.map((g,i)=>{const share=canShare&&g.revenue!==null?g.revenue/total*100:0;return `<tr><td><div class="channel-name"><span class="color-dot" style="background:${colors[i%colors.length]}"></span>${escapeHTML(g.label)}</div></td><td>${money(g.spend)}</td><td>${money(g.revenue)}</td><td>${count(g.conversions)}</td><td>${ratio(g.roas)}</td><td>${g.revenue!==null&&canShare?`${share.toFixed(0)}%`:'—'}<div class="bar-track"><div class="bar-fill" style="width:${share}%;background:${colors[i%colors.length]}"></div></div></td></tr>`}).join('')}</tbody></table></div><p class="footnote">*Share of recorded ${valueWord()}; hidden when any channel value is negative. Totals can be partial; ROAS needs complete spend and value for that channel.</p></div>`;
}
function insights(cur,prev){
 if(!cur.count)return [{title:'Your story starts here',body:'Add your marketing data and Waddle will help you spot what stands out.'},{title:'No guesswork required',body:'Insights are calculated from the rows you upload.'}];
 const out=[];for(const key of ['revenue','conversions','spend']){
  const n=summaryChange(cur,prev,key); if(n!==null){const label=key==='revenue'?valueLabel():key[0].toUpperCase()+key.slice(1);const direction=n>0?'up':n<0?'down':'unchanged';const verb=key==='conversions'?'are':'is';out.push({title:`${label} ${n===0?`${verb} unchanged`:`${verb} ${direction} ${Math.abs(n).toFixed(1)}%`}`,body:`${metricText(key,cur[key])} in this period vs. ${metricText(key,prev[key])} in the previous window.`});}
 }
 if(!out.length)out.push({title:'Your data is ready to explore',body:'Change comparisons need records for every date in both windows and complete metric values.'});
 if(cur.roas!==null)out.push({title:`Recorded ROAS is ${ratio(cur.roas)}`,body:`${valueLabel()} divided by spend for the selected records.`});
 return out.slice(0,3);
}
function recommendation(rows){
 if(!rows.length)return 'Upload a CSV to see a practical next step based on your own numbers.';
 const candidates=groupBy(rows,'channel').filter(g=>g.roas!==null && g.spend>0).sort((a,b)=>b.roas-a.roas);
 if(!candidates.length)return `Review your channel breakdown. Add complete spend and ${valueWord()} values to compare return on ad spend.`;
 const top=candidates[0];return `Review ${escapeHTML(top.label)}: its recorded ROAS is ${ratio(top.roas)}. Check conversion volume and profitability before changing its budget.`;
}
function overview(period){
 const cur=summarize(period.current), prev=priorSummary(period);
 const goalNote=state.data?`<div class="goal-note"><strong>Your goal: ${escapeHTML(state.goal)}</strong> · ${complete(cur,'spend')&&complete(cur,'conversions')&&cur.conversions>0?`Recorded cost per conversion: ${money(cur.spend/cur.conversions)}. Check that your conversion definition matches your goal.`:'Cost per conversion needs complete spend and a positive conversion count.'}</div>`:'';
 const welcome=!state.data?`<section class="welcome-window"><div><span class="eyebrow">WELCOME TO YOUR LITTLE WORKSPACE ✦</span><h2>Let’s make sense of those numbers.</h2><p>Bring your marketing data in, then find the stories hiding behind the numbers.</p><div class="welcome-actions"><button class="button button-primary" data-upload>↥ &nbsp; Upload your CSV</button><button class="button button-soft" data-example>Explore demo →</button><a class="button button-soft" href="#guide">How it works</a></div><small>Free to use · Your data stays in this browser</small></div><img src="./assets/waddle.svg" alt=""></section>`:'';
 return `${welcome}${goalNote}${metrics(cur,prev)}<div class="dashboard-grid"><section class="panel performance"><div class="panel-heading"><div><h2>Performance</h2><p>Recorded values by marketing channel</p></div><div class="chart-controls"><label><span class="sr-only">Chart metric</span><select id="chart-metric"><option value="revenue" ${state.metric==='revenue'?'selected':''}>${valueLabel()}</option><option value="spend" ${state.metric==='spend'?'selected':''}>Spend</option><option value="conversions" ${state.metric==='conversions'?'selected':''}>Conversions</option><option value="clicks" ${state.metric==='clicks'?'selected':''}>Clicks</option><option value="impressions" ${state.metric==='impressions'?'selected':''}>Impressions</option></select></label>${dateSelect()}</div></div>${chart(period.current)}${channelTable(period.current)}</section><div class="side-stack"><section class="panel insight-card"><img class="mascot" src="./assets/waddle.svg" alt=""><div class="card-title"><span class="title-star" aria-hidden="true">✦</span><h2>Your Waddle Briefing</h2></div><div class="insight-list">${insights(cur,prev).map((item,i)=>`<div class="insight-row"><span class="insight-badge" aria-hidden="true">${i===0?'↗':i===1?'✦':'↟'}</span><div><strong>${escapeHTML(item.title)}</strong><details><summary>Show me why</summary><p>${escapeHTML(item.body)}</p><p>${escapeHTML(dateLabel(period.start))} – ${escapeHTML(dateLabel(period.end))}. Descriptive, not proof of cause.</p></details></div></div>`).join('')}</div></section><section class="panel step-card"><p class="eyebrow">MYSTERY LAB ✦</p><h3>Have a marketing mystery?</h3><p>Follow the evidence and turn a question into a next step.</p><a class="button button-soft" href="#mystery">Open a case →</a></section><section class="panel step-card"><div class="card-title"><span class="step-icon" aria-hidden="true">⚑</span><h2>Your next little step</h2></div><p>${recommendation(period.current)}</p>${!state.data?'<button class="text-button step-action" data-upload>Upload your CSV →</button>':'<a class="text-button step-action" href="#planner">Plan a little experiment →</a>'}</section><p class="hint">✧ Comparisons need records for every date in both windows. Insights describe your data, not proof of what caused a change.</p></div></div>`;
}
function emptyBlock(heading,detail){return `<div class="empty-state"><img class="empty-waddle" src="./assets/waddle.svg" alt=""><h3>${heading}</h3><p>${detail}</p><div class="empty-actions"><button class="button button-primary" data-upload>Upload CSV</button><button class="button button-soft" data-example>Try sample data</button></div></div>`}
function campaigns(period){
 if(!state.data)return `<section class="panel wide-panel">${emptyBlock('Let’s get those campaigns in here','Import a CSV with a campaign column to explore performance.')}</section>`;
 let groups=groupBy(period.current,'campaign'); groups.sort((a,b)=>state.sort==='name'?a.label.localeCompare(b.label):(b[state.sort]??-Infinity)-(a[state.sort]??-Infinity));const q=state.search.toLowerCase().trim();if(q)groups=groups.filter(g=>g.label.toLowerCase().includes(q));
 return `<section class="panel wide-panel"><div class="panel-heading"><div><h2>Campaigns at a glance</h2><p>Compare the campaigns in your selected period.</p></div>${dateSelect()}</div><div class="toolbar"><input id="campaign-search" class="search" type="search" placeholder="Search campaigns" aria-label="Search campaigns" value="${escapeHTML(state.search)}"><label>Sort by <select id="campaign-sort"><option value="revenue" ${state.sort==='revenue'?'selected':''}>${valueLabel()}</option><option value="spend" ${state.sort==='spend'?'selected':''}>Spend</option><option value="conversions" ${state.sort==='conversions'?'selected':''}>Conversions</option><option value="roas" ${state.sort==='roas'?'selected':''}>ROAS</option><option value="name" ${state.sort==='name'?'selected':''}>Name</option></select></label><span class="hint">${groups.length} campaign${groups.length===1?'':'s'}</span></div><div class="table-scroll"><table><thead><tr><th>Campaign</th><th>Spend</th><th>${valueLabel()}</th><th>Conversions</th><th>ROAS</th><th>Rows</th></tr></thead><tbody>${groups.map(g=>`<tr><td><button class="text-button" data-campaign="${encodeURIComponent(g.label)}">${escapeHTML(g.label)}</button></td><td>${money(g.spend)}</td><td>${money(g.revenue)}</td><td>${count(g.conversions)}</td><td>${ratio(g.roas)}</td><td>${g.count}</td></tr>`).join('')||'<tr><td colspan="6">No matching campaigns in this period.</td></tr>'}</tbody></table></div>${campaignDetail(period.current)}<p class="footnote">Campaigns with the same name are grouped together across channels. Missing campaign names appear as “Unassigned campaign”. Totals can be partial; ROAS requires complete spend and ${valueWord()}.</p></section>`;
}
function campaignDetail(rows){if(!state.campaign)return '';const label=state.campaign;const selected=rows.filter(r=>(r.campaign||'Unassigned campaign')===label);if(!selected.length)return '';const sum=summarize(selected), channels=[...new Set(selected.map(r=>r.channel))];return `<div class="info-card"><h3>${escapeHTML(label)}</h3><p>Channels: ${channels.map(escapeHTML).join(', ')} · ${selected.length} records · Spend ${money(sum.spend)} · ${valueLabel()} ${money(sum.revenue)} · Conversions ${count(sum.conversions)} · ROAS ${ratio(sum.roas)}</p><p class="footnote">Spend present on ${sum.spendCoverage} rows; ${valueWord()} on ${sum.revenueCoverage}. Values may be partial.</p>${chart(selected)}</div>`}
function channelsPage(period){
 if(!state.data)return `<section class="panel wide-panel">${emptyBlock('Your channels, all together','Add your CSV to see a breakdown of your recorded channels.')}</section>`;
 const total=summarize(period.current), groups=groupBy(period.current,'channel');
 return `<section class="panel wide-panel"><div class="panel-heading"><div><p class="eyebrow">THE CHANNEL DESK ✦</p><h2>See where the story unfolds.</h2><p>Compare the channels in your selected date range.</p></div>${dateSelect()}</div><div class="channel-cards">${groups.map((g,i)=>`<article class="channel-card"><span class="color-dot" style="background:${colors[i%colors.length]}"></span><h3>${escapeHTML(g.label)}</h3><strong>${money(g.revenue)}</strong><p>recorded ${valueWord()} · ${g.count} rows</p><div><span>Spend <b>${money(g.spend)}</b></span><span>ROAS <b>${ratio(g.roas)}</b></span></div><small>${valueLabel()} present on ${g.revenueCoverage} of ${g.count} rows.</small></article>`).join('')}</div>${channelTable(period.current)}<p class="footnote">Values come from the uploaded rows. Blank values are not zero. ROAS = recorded ${valueWord()} ÷ spend only when both are complete and spend is positive. Totals may be partial.</p></section>`;
}
function dataPage(period){
 const d=state.data, summary=summarize(period.current);
 return `<section class="panel wide-panel"><p class="eyebrow">YOUR DATA, YOUR SPACE ✦</p><h2>A little housekeeping.</h2><p>Your CSV stays in this browser session. Refreshing or leaving clears it.</p><div class="info-grid"><article class="info-card"><h3>Current dataset</h3><p>${d?`${escapeHTML(state.name)} ${state.example?'(sample data)':''}<br>${d.records.length.toLocaleString()} valid records · ${d.errors.length} skipped<br>Reporting currency: ${escapeHTML(d.currency)}`:'No data loaded yet.'}</p></article><article class="info-card"><h3>What goes in</h3><p>CSV needs a date, channel, and at least one metric. Use dates like YYYY-MM-DD or MM/DD/YYYY and one currency per file.</p></article><article class="info-card"><h3>What stays private</h3><p>Files are read locally. No account, sync, or data transfer is required. There is no persistent storage.</p></article></div><div class="welcome-actions"><button class="button button-primary" data-upload>Upload CSV</button><button class="button button-soft" id="download-template">↓ Download template</button>${d?'<button class="text-button" data-clear>Clear current data</button>':''}</div><p class="footnote">Values are summed as provided; duplicates and overlapping summary rows are not removed. Data is not automatically converted between currencies.</p></section>`;
}
function insightsPage(period){
 if(!state.data)return `<section class="panel wide-panel">${emptyBlock('A little insight goes a long way','Upload your marketing data to see what stands out.')}</section>`;
 const cur=summarize(period.current),prev=priorSummary(period),cards=insights(cur,prev),campaigns=groupBy(period.current,'campaign').filter(x=>x.spend!==null).sort((a,b)=>b.spend-a.spend),top=campaigns[0];
 return `<section class="panel wide-panel"><div class="panel-heading"><div><p class="eyebrow">WADDLE'S NOTES ✦</p><h2>A closer look</h2><p>Observations grounded in your uploaded data.</p></div>${dateSelect()}</div><div class="info-grid"><article class="info-card"><p class="eyebrow">CHANGES IN YOUR DATA</p>${cards.map(x=>`<h3>✦ ${escapeHTML(x.title)}</h3><p>${escapeHTML(x.body)}</p>`).join('')}<small>${escapeHTML(dateLabel(period.start))} – ${escapeHTML(dateLabel(period.end))}</small></article><article class="info-card"><p class="eyebrow">WORTH A CLOSER LOOK</p><h3>${top?'A campaign to review':'Start with your channels'}</h3><p>${top?`${escapeHTML(top.label)} has the highest recorded spend (${money(top.spend)}). Spend is present on ${top.spendCoverage} of its ${top.count} records; totals can be partial.`:'A campaign with spend data is needed to compare recorded spend.'}</p><a href="#campaigns" class="text-button">Explore campaigns →</a></article><article class="info-card"><p class="eyebrow">THINGS WE CAN’T TELL YET</p><h3>Check your data coverage</h3><p>In ${cur.count} selected rows, spend is present on ${cur.spendCoverage}, ${valueWord()} on ${cur.revenueCoverage}, and conversions on ${cur.conversionsCoverage}. A blank is not zero. The file does not prove what caused a change.</p></article><article class="info-card"><p class="eyebrow">YOUR NEXT LITTLE STEP</p><h3>Try a thoughtful experiment</h3><p>${recommendation(period.current)}</p><a href="#planner" class="text-button">Plan your next step →</a></article></div><div class="notice">Comparisons use the previous equal-length date window only when both windows contain records on every date and the metric is complete. A date having records doesn’t guarantee a complete export.</div></section>`;
}
function answer(question,period){
 const s=summarize(period.current), groups=groupBy(period.current,'channel');
 if(!period.current.length)return 'Add a CSV first, then pick a question and I’ll look at your recorded numbers.';
 if(question==='best'){const g=groups.filter(g=>g.roas!==null).sort((a,b)=>b.roas-a.roas)[0];return g?`${g.label} has the highest recorded ROAS at ${ratio(g.roas)} (${money(g.revenue)} ${valueWord()} ÷ ${money(g.spend)} spend). Review volume and profit too; ROAS alone is not profit.`:'I need complete spend and value for at least one channel to compare ROAS.'}
 if(question==='revenue'){const g=groups.find(g=>g.revenue!==null);return g?`${g.label} has the most recorded ${valueWord()} at ${money(g.revenue)} in the selected period. Totals can be partial if values are missing.`:'I couldn’t find a value in this period.'}
 if(question==='changes'){const p=priorSummary(period), cs=insights(s,p);return cs.map(x=>`${x.title}. ${x.body}`).join(' ')}
 if(question==='coverage')return `There are ${s.count} rows in this period. Spend is present on ${s.spendCoverage}, ${valueWord()} on ${s.revenueCoverage}, and conversions on ${s.conversionsCoverage}. Blank cells are not treated as zero.`;
 return 'Choose a question below and I’ll use the numbers in your selected date range.';
}
function askPage(period){return `<section class="panel wide-panel"><div class="panel-heading"><div><h2>Hi, I’m Waddle. ✦</h2><p>Pick a question for a quick, numbers-first answer.</p></div>${state.data?dateSelect():''}</div><div class="question-list"><button class="question" data-question="best">Which channel has the best ROAS?</button><button class="question" data-question="revenue">Where is ${valueWord()} highest?</button><button class="question" data-question="changes">What changed?</button><button class="question" data-question="coverage">Is my data complete?</button></div><div class="answer" role="status">${escapeHTML(answer(state.question,period))}</div><p class="footnote">These answers use simple rules and your uploaded data, not AI. They don’t establish causation or account for profit.</p>${!state.data?'<button class="button button-soft" data-upload>Upload CSV</button>':''}</section>`}
function guidePage(){return `<section class="panel wide-panel guide"><p class="eyebrow">START HERE ✦</p><h2>Welcome to your little marketing office.</h2><p>Bring a supported campaign report, see the recorded results, and turn what you find into a report and a next step.</p><div class="info-grid"><article class="info-card"><h3>1. Bring your data</h3><p>Choose a custom CSV or a daily Google Ads campaign report. Check the mappings and warnings before import.</p></article><article class="info-card"><h3>2. Explore the story</h3><p>Filter dates, compare channels, and open campaigns. Waddle explains only what the uploaded values support.</p></article><article class="info-card"><h3>3. Make it useful</h3><p>Write a small experiment and edit your Waddle Report. Print it or use your browser’s Save as PDF option.</p></article></div><h3>What should my CSV look like?</h3><p>Use a UTF-8 comma-separated file with the headers in the first row. Each data row should represent one channel or campaign on one day. Dates must be YYYY-MM-DD or MM/DD/YYYY. Use decimal points and a single currency.</p><div class="table-scroll"><table><thead><tr><th>Date</th><th>Channel</th><th>Campaign</th><th>Spend</th><th>Revenue</th><th>Conversions</th></tr></thead><tbody><tr><td>2026-10-01</td><td>Paid Search</td><td>Autumn</td><td>100</td><td>400</td><td>8</td></tr></tbody></table></div><p class="footnote">Date and Channel are required, plus at least one of Spend, Revenue, Conversions, Clicks, or Impressions. Campaign is optional. A Google Ads-style export may use Day, Campaign, Cost, Conversions, and Conv. value; assign the channel yourself if it is absent. Choose whether your value column is actual revenue or platform-reported conversion value. Unsupported report shapes, localized dates, CRM contact lists, summary rows, or mixed currencies may need editing first.</p><div class="notice">Use one report level and avoid overlapping totals. Exact duplicate rows are flagged but never silently removed. Waddle cannot detect every duplicate or establish causation.</div><div class="welcome-actions"><button class="button button-primary" data-upload>Upload a report</button><button class="button button-soft" id="download-template">↓ Download the template</button><button class="button button-soft" data-example>Explore demo</button></div><p class="footnote">Your CSV stays in browser memory for this session. Refreshing or leaving clears it. Ask Waddle uses rules, not AI.</p></section>`}

function mysteryPage(period){
 const type=state.caseType||'expensive', result=investigate(type,period,state.days);
 const options=[['expensive','01','Expensive conversions','Compare cost per conversion across two periods.'],['spending','02','Campaign spending','Find where recorded campaign spend went.'],['results','03','Disappearing results','Compare recorded conversions across two periods.']];
 const cards=options.map(([key,num,title,desc])=>`<button class="case-choice ${type===key?'chosen':''}" data-case="${key}" aria-pressed="${type===key}"><small>CASE ${num}</small><strong>${title}</strong><span>${desc}</span></button>`).join('');
 let body=result.error?`<div class="case-empty"><h3>We need another clue.</h3><p>${escapeHTML(result.error)}</p><button class="button button-soft" data-upload>Upload a report</button> <button class="button button-soft" data-example>Explore demo</button></div>`:`<div class="case-file"><div class="case-file-head"><div><p class="eyebrow">CASE FILE · ${state.example?'DEMO DATA · ':''}RULE-BASED INVESTIGATION</p><h2>${escapeHTML(result.title)}</h2><p>${escapeHTML(dateLabel(period.start))} – ${escapeHTML(dateLabel(period.end))}</p></div><span class="case-stamp">EVIDENCE<br>INSIDE ✦</span></div>${type==='spending'?`<div class="case-evidence"><article><small>RECORDED SPEND</small><strong>${money(result.total)}</strong><span>${result.current.count} selected rows</span></article></div><h3>Where the spend went</h3><div class="table-scroll"><table><thead><tr><th>Campaign</th><th>Recorded spend</th><th>Rows</th></tr></thead><tbody>${result.facts.map(x=>`<tr><td>${escapeHTML(x.label)}</td><td>${money(x.value)}</td><td>${x.rows}</td></tr>`).join('')}</tbody></table></div>`:`<p class="case-period">Previous: ${escapeHTML(dateLabel(result.previousStart))} – ${escapeHTML(dateLabel(result.previousEnd))} · Current: ${escapeHTML(dateLabel(period.start))} – ${escapeHTML(dateLabel(period.end))}</p><div class="case-evidence">${type==='expensive'?`<article><small>SPEND</small><strong>${money(result.previous.spend)} → ${money(result.current.spend)}</strong></article>`:''}<article><small>RECORDED CONVERSIONS</small><strong>${count(result.previous.conversions)} → ${count(result.current.conversions)}</strong></article>${type==='expensive'?`<article><small>COST PER CONVERSION</small><strong>${money(result.previous.spend/result.previous.conversions)} → ${money(result.current.spend/result.current.conversions)}</strong><span>Spend ÷ conversions</span></article>`:''}</div><h3>Campaign clues</h3>${result.changes.length?`<div class="table-scroll"><table><thead><tr><th>Campaign</th><th>Previous conversions</th><th>Current conversions</th>${type==='expensive'?'<th>Spend change</th>':''}</tr></thead><tbody>${result.changes.slice(0,8).map(x=>`<tr><td>${escapeHTML(x.label)}</td><td>${count(x.previous.conversions)}</td><td>${count(x.current.conversions)}</td>${type==='expensive'?`<td>${money(x.current.spend-x.previous.spend)}</td>`:''}</tr>`).join('')}</tbody></table></div><p class="footnote">Showing up to eight named campaigns present with complete required values in both periods, ordered by ${type==='expensive'?'spend change':'conversion change'}. This is not a causal contribution analysis; other campaigns may be absent.</p>`:'<p>No named campaigns have complete data in both periods. The overall comparison is still shown above.</p>'}`}<div class="case-notes"><article><h3>What we can’t tell yet</h3><p>${escapeHTML(result.note)} The numbers do not prove what caused a change; creative, targeting, tracking and context are not in this report.</p></article><article><h3>Your next little step</h3><p>${escapeHTML(result.next)}</p><button class="button button-primary" data-case-plan>Make a test card →</button> <button class="button button-soft" data-case-report>Add case to report →</button></article></div><p class="footnote">Recommendations are for human review. Check source definitions, duplicate rows, and coverage before making decisions.</p></div>`;
 return `<section class="mystery-intro"><div><p class="eyebrow">WELCOME TO WADDLE’S MYSTERY LAB ✦</p><h2>Let’s follow the clues.</h2><p>Pick a question, examine the evidence, and leave with a small plan. Your data stays in this browser.</p></div><img src="./assets/waddle.svg" alt=""></section><div class="case-toolbar"><h2>Choose your case</h2>${state.data?dateSelect():''}</div><div class="case-choices">${cards}</div>${state.example?'<div class="notice">DEMO DATA — This investigation uses fictional numbers.</div>':''}${body}`;
}
function caseText(period){const r=investigate(state.caseType||'expensive',period,state.days);if(r.error)return null; const t=state.caseType||'expensive';return `${r.title} (${dateLabel(period.start)} – ${dateLabel(period.end)}): ${t==='spending'?`Recorded spend ${money(r.total)}. ${r.facts.slice(0,3).map(x=>`${x.label}: ${money(x.value)}`).join('; ')}.`:`Previous ${dateLabel(r.previousStart)} – ${dateLabel(r.previousEnd)}: ${count(r.previous.conversions)} conversions${t==='expensive'?`, ${money(r.previous.spend)} spend and ${money(r.previous.spend/r.previous.conversions)} per conversion`:''}. Current: ${count(r.current.conversions)} conversions${t==='expensive'?`, ${money(r.current.spend)} spend and ${money(r.current.spend/r.current.conversions)} per conversion`:''}.`} ${r.note} These figures do not establish causation. Next step: ${r.next}`}

function plannerPage(period){const fields=[['noticed','What I noticed'],['hypothesis','What I think might be happening'],['test','What I’ll test'],['measure','What I’ll measure'],['review','When I’ll review it'],['limits','What this data doesn’t prove']];return `<section class="panel wide-panel"><p class="eyebrow">THE EXPERIMENT DESK ✦</p><h2>One small step at a time.</h2><p>Use your judgment to turn an observation into a test. Waddle will never change a campaign or budget for you.</p>${state.example?'<div class="notice">DEMO DATA — This plan is for the fictional dataset.</div>':''}${state.data?`<div class="notice"><strong>Starting point:</strong> ${recommendation(period.current)}</div>`:''}<div class="planner-grid">${fields.map(([key,label])=>`<label>${label}<textarea data-plan-field="${key}" rows="3" placeholder="Add your thoughts…">${escapeHTML(state.plan[key]||'')}</textarea></label>`).join('')}</div><div class="welcome-actions"><button class="button button-soft" data-copy-plan>Copy plan</button><a class="button button-primary" href="#report">Add to Waddle Report →</a></div><p class="footnote">Plans stay in this browser session and clear when you refresh or leave. Recommendations are for human review.</p></section>`}
function reportPage(period){if(!state.data)return `<section class="panel wide-panel">${emptyBlock('Let’s make a report together','Upload a supported CSV or explore the demo to start your briefing.')}</section>`;const sum=summarize(period.current),prior=priorSummary(period),facts=insights(sum,prior),fields=[['spend','Spend'],['revenue',state.data.valueKind==='conversion'?'Platform-reported conversion value':'Revenue'],['conversions','Conversions'],['clicks','Clicks'],['impressions','Impressions'],['roas','ROAS']];const narrative=state.report.summary??facts.map(x=>`${x.title}: ${x.body}`).join('\n');const title=state.report.title??'My Waddle Report';const isIncluded=key=>state.report['include_'+key]??(sum[key]!==null);const included=fields.filter(([key])=>isIncluded(key));const planText=Object.entries(state.plan).filter(([,v])=>v.trim()).map(([k,v])=>`${({noticed:'What I noticed',hypothesis:'What I think might be happening',test:'What I’ll test',measure:'What I’ll measure',review:'When I’ll review it',limits:'What this data doesn’t prove'})[k]||k}: ${v}`).join('\n');return `<section class="panel wide-panel report-sheet" id="report-sheet"><div class="report-top"><div><p class="eyebrow">YOUR WADDLE REPORT ✦ ${state.example?' · DEMO DATA':''}</p><h2>Make this report yours.</h2><p>Edit the title, observations, and notes before printing.</p><span class="no-print">${dateSelect()}</span></div><img src="./assets/waddle-notes.webp" alt=""></div>${state.example?'<div class="notice">DEMO DATA — All values in this report are fictional.</div>':''}<div class="report-controls"><label>Report title<input data-report-field="title" value="${escapeHTML(title)}"></label><fieldset><legend>Include metrics</legend>${fields.map(([key,label])=>`<label class="check-label"><input type="checkbox" data-report-check="include_${key}" ${isIncluded(key)?'checked':''}> ${label}</label>`).join('')}</fieldset></div><div class="report-context"><strong>${escapeHTML(state.name)}</strong> · ${state.data.source==='google'?'Google Ads campaign report':state.data.source==='demo'?'Demo report':'Custom / other CSV'} · ${escapeHTML(dateLabel(period.start))} – ${escapeHTML(dateLabel(period.end))} · ${sum.count} records · ${escapeHTML(state.goal)}${state.data.valueKind==='conversion'?' · Platform-reported conversion value':''}</div><div class="report-metrics">${included.map(([key,label])=>`<div><span>${label}</span><strong>${metricText(key,sum[key]??null)}</strong>${key!=='roas'&&sum[`${key}Coverage`]<sum.count?'<small>Partial data</small>':''}</div>`).join('')}</div><label class="report-label">Observations<textarea data-report-field="summary" rows="7">${escapeHTML(narrative)}</textarea></label><div class="notice"><strong>Data quality:</strong> ${sum.count} selected records; spend present on ${sum.spendCoverage}, value on ${sum.revenueCoverage}, conversions on ${sum.conversionsCoverage}. ${state.data.errors.length} imported records were skipped. ${state.data.duplicates||0} exact duplicates were flagged. Blank values are not zero. Comparisons describe recorded data and do not establish cause.${state.data.valueKind==='conversion'?' Platform-reported conversion value is not verified revenue or profit.':''}</div><label class="report-label">Experiment plan<textarea data-report-field="experiment" rows="6">${escapeHTML(state.report.experiment??planText)}</textarea></label><label class="report-label">Your notes<textarea data-report-field="notes" rows="4" placeholder="Add context your spreadsheet can’t see…">${escapeHTML(state.report.notes||'')}</textarea></label><div class="welcome-actions no-print"><button class="button button-primary" data-print>Print / Save as PDF</button><a class="button button-soft" href="#planner">Edit your next step</a></div><p class="footnote">Review all figures and notes before sharing. Edited observations stay as written when you change dates. Use your browser’s print dialog to save as PDF. This report stays in your current session.</p></section>`}

function render(){
 state.page=getPage();document.querySelectorAll('.nav-link').forEach(a=>{const active=a.dataset.page===state.page;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});
 const titles={mystery:['Open a little <span>case file.</span>','Follow the clues in your marketing data.'],overview:['Your marketing, all in one <span>cozy place.</span>','A little perspective makes a big difference.'],campaigns:['Every campaign has a <span>story.</span>','Find the little details behind the big picture.'],channels:['Every channel has a <span>story.</span>','A closer look at where your results come from.'],data:['A tidy little <span>workspace.</span>','Keep track of what is in your dashboard.'],report:['A little report, <span>made by you.</span>','Turn your numbers into a briefing you can share.'],planner:['A little step <span>forward.</span>','Turn an observation into a thoughtful experiment.'],guide:['Welcome to <span>Waddle Dash.</span>','A friendly guide to your first report.'],insights:['The good stuff, <span>uncovered.</span>','Turn the numbers into a little more clarity.'],ask:['A little help from <span>Waddle.</span>','A friendly guide to the numbers in front of you.']};
 $('#page-title').innerHTML=titles[state.page][0];$('#page-subtitle').textContent=titles[state.page][1];
 document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===state.mode)));
 const period=currentPeriod(),bar=$('#dataset-bar');bar.hidden=!state.data;
 if(state.data){const warning=state.data.errors.length?` · ${state.data.errors.length} skipped`:'';bar.innerHTML=`<span class="dot"></span><span class="file-name">${escapeHTML(state.name)}</span>${state.example?'<span class="tag">SAMPLE DATA</span>':''}<span>· ${state.data.records.length.toLocaleString()} rows${warning} · ${escapeHTML(dateLabel(period.start))} – ${escapeHTML(dateLabel(period.end))}</span><button class="text-button" data-clear>Clear</button>`;}
 const warnings=state.data?.errors.length?`<div class="notice" role="status"><strong>${state.data.errors.length} record(s) skipped:</strong> ${state.data.errors.slice(0,5).map(e=>`record ${e.record}: ${escapeHTML(e.reason)}`).join('; ')}${state.data.errors.length>5?'; and more':''}. Record numbers count data records after the header, including quoted multiline records. Review the records in your file; identifiable summary rows are excluded to avoid double-counting.</div>`:'';
 content.innerHTML=warnings+(state.page==='mystery'?mysteryPage(period):state.page==='overview'?overview(period):state.page==='campaigns'?campaigns(period):state.page==='channels'?channelsPage(period):state.page==='data'?dataPage(period):state.page==='report'?reportPage(period):state.page==='planner'?plannerPage(period):state.page==='guide'?guidePage():state.page==='insights'?insightsPage(period):askPage(period));
}
function mappingOptions(selected){return `<option value="-1">Not mapped</option>${state.parsed.headers.map((h,i)=>`<option value="${i}" ${selected===i?'selected':''}>${escapeHTML(h)}</option>`).join('')}`}
function showMapping(parsed,filename){state.parsed=parsed;state.pendingName=filename;const map=suggestMapping(parsed.headers);if($('#report-source').value==='google'){const i=parsed.headers.findIndex(h=>/^(conv\.?\s*value|conversion value)$/i.test(h.trim()));if(i>=0&&map.revenue<0)map.revenue=i;$('#value-kind').value='conversion';}else $('#value-kind').value='revenue';const fields=[['date','Date *'],['channel','Channel *'],['campaign','Campaign'],['spend','Spend'],['revenue','Revenue or conversion value'],['conversions','Conversions'],['clicks','Clicks'],['impressions','Impressions'],['currency','Currency column']];$('#mapping-fields').innerHTML=fields.map(([key,label])=>`<label>${label}<select data-map="${key}">${mappingOptions(map[key])}</select></label>`).join('');$('#csv-preview').innerHTML=`<div class="preview-box"><strong>First few records</strong><div class="table-scroll"><table><thead><tr>${parsed.headers.map(h=>`<th>${escapeHTML(h)}</th>`).join('')}</tr></thead><tbody>${parsed.rows.slice(0,3).map(row=>`<tr>${parsed.headers.map((_,i)=>`<td>${escapeHTML((row[i]||'').slice(0,100))}</td>`).join('')}</tr>`).join('')}</tbody></table></div><small>Preview only. Check your mappings below before importing.</small></div>`;$('#file-name').textContent=filename;$('#file-info').textContent=`${parsed.rows.length.toLocaleString()} rows · ${parsed.headers.length} columns`;$('#upload-start').hidden=true;$('#mapping').hidden=false;$('#upload-error').textContent='';$('#mapping-error').textContent='';updatePreflight();}
function updatePreflight(){if(!state.parsed)return;const target=$('#preflight');try{const mapping=Object.fromEntries([...document.querySelectorAll('[data-map]')].map(el=>[el.dataset.map,Number(el.value)]));const result=normalizeData(state.parsed,mapping,$('#currency').value,{defaultChannel:$('#default-channel').value});const details=result.errors.slice(0,3).map(e=>`record ${e.record}: ${e.reason}`).join('; ');target.textContent=`Ready to import ${result.records.length} records. ${result.errors.length} will be skipped${details?': '+details:''}. ${result.duplicates} exact duplicate records detected (not removed). Blank cells remain missing; check for overlapping totals.`;}catch(error){target.textContent=error.message;}}
function resetUpload(){state.parsed=null;$('#file-input').value='';$('#upload-start').hidden=false;$('#mapping').hidden=true;$('#upload-error').textContent='';$('#mapping-error').textContent=''}
function updateFormatGuide(){const source=$('#report-source').value;$('#format-guide').innerHTML=source==='google'?'<strong>Google Ads campaign report:</strong> Export a CSV with one row per campaign per day: Day, Campaign, Cost, Conversions and Conv. value. Remove title and total rows before export. Not every export is supported. Assign a channel yourself if it is missing.':source==='other'?'<strong>Other reports:</strong> Map a date, channel and at least one numeric metric. A CRM contact or deal list may not work as a campaign report.':'<strong>Custom format:</strong> Use a header row with Date, Channel, Campaign (optional), and at least one of Spend, Revenue, Conversions, Clicks, or Impressions. Each row should represent one channel or campaign on one day.'; }
function openUpload(){resetUpload();updateFormatGuide();if(!dialog.open)dialog.showModal()}
async function processFile(file){if(!file)return;$('#upload-error').textContent='';if(file.size>5*1024*1024){$('#upload-error').textContent='This file is larger than 5 MB. Please split it into smaller files.';return}if(!/\.csv$/i.test(file.name)&&file.type!=='text/csv'){$('#upload-error').textContent='Please choose a CSV file.';return}try{const parsed=parseCSV(await file.text());showMapping(parsed,file.name)}catch(error){$('#upload-error').textContent=error.message}}
function commitImport(){try{const mapping=Object.fromEntries([...document.querySelectorAll('[data-map]')].map(el=>[el.dataset.map,Number(el.value)]));const result=normalizeData(state.parsed,mapping,$('#currency').value,{defaultChannel:$('#default-channel').value});if(state.mode==='demo')switchMode('personal');if(state.data && !confirm('Replace your current uploaded dataset?'))return;if(result.duplicates && !confirm(`${result.duplicates} exact duplicate records were found. They are not removed and could double-count results. Import them anyway?`))return;result.valueKind=$('#value-kind').value;result.source=$('#report-source').value;state.data=result;state.name=state.pendingName;state.goal=$('#report-goal').value;state.report={};state.plan={};state.example=false;state.days='30';state.search='';state.question='';dialog.close();location.hash='#overview';render();}catch(error){$('#mapping-error').textContent=error.message}}
function sampleData(){switchMode('demo');if(dialog.open)dialog.close();location.hash='#overview';render()}
function makeSample(){const rows=[];const channels=[['Paid Search','Search — Spring',60,240,3],['Paid Social','Social — Launch',45,146,2],['Email','Email — Welcome',15,65,1]];for(let d=0;d<60;d++){const day=new Date(Date.UTC(2026,7,1+d)).toISOString().slice(0,10);channels.forEach(([channel,campaign,spend,revenue,conversions],i)=>rows.push({date:day,channel,campaign,spend:spend+(d%6)*2,revenue:revenue+(d%8)*8+i*3,conversions:conversions+(d%3)}));}return {data:{records:rows,errors:[],currency:'USD',valueKind:'revenue',source:'demo'},name:'Sample marketing data',example:true,goal:'Sales',report:{},plan:{}}}
function switchMode(mode){if(mode===state.mode)return;slots[state.mode]={data:state.data,name:state.name,example:state.example,goal:state.goal,report:state.report,plan:state.plan};const slot=slots[mode]||(mode==='demo'?makeSample():{data:null,name:'',example:false,goal:'Sales',report:{},plan:{}});Object.assign(state,slot,{mode,search:'',question:''});render()}
function downloadTemplate(){const csv='Date,Channel,Campaign,Spend,Revenue,Conversions,Currency\n2026-01-01,Paid Search,Spring Launch,100,450,8,USD\n2026-01-02,Email,Welcome Series,20,120,3,USD\n';const blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='waddle-dash-template.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
window.addEventListener('beforeprint',()=>{document.querySelectorAll('.print-copy').forEach(el=>el.remove());document.querySelectorAll('#report-sheet textarea,#report-sheet input[data-report-field]').forEach(el=>{const copy=document.createElement('div');copy.className='print-copy';copy.textContent=el.value;el.after(copy)})});
window.addEventListener('afterprint',()=>document.querySelectorAll('.print-copy').forEach(el=>el.remove()));
window.addEventListener('hashchange',render);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.case){state.caseType=b.dataset.case;render()}else if(b.matches('[data-case-plan]')){const p=currentPeriod(), text=caseText(p), r=investigate(state.caseType||'expensive',p,state.days);if(text&&(!Object.values(state.plan).some(Boolean)||confirm('Replace the current experiment plan with this case?'))){state.plan={noticed:text,test:r.next,measure:(state.caseType||'expensive')==='spending'?'Recorded spend and conversions':'Conversions and cost per conversion',limits:'The recorded data does not establish cause.'};location.hash='#planner'}}else if(b.matches('[data-case-report]')){const text=caseText(currentPeriod());if(text&&(!state.report.summary||confirm('Replace your report observations with this case?'))){state.report.summary=text;location.hash='#report'}}else if(b.dataset.campaign){state.campaign=decodeURIComponent(b.dataset.campaign);render()}else if(b.dataset.mode){switchMode(b.dataset.mode);render()}else if(b.matches('[data-print]'))window.print();else if(b.matches('[data-copy-plan]')){const text=Object.entries(state.plan).map(([k,v])=>`${k}: ${v}`).join('\n');Promise.resolve().then(()=>navigator.clipboard.writeText(text)).then(()=>{b.textContent='Copied!'}).catch(()=>{b.textContent='Copy unavailable — select the text instead'});}else if(b.matches('[data-upload]'))openUpload();else if(b.matches('[data-close-dialog]'))dialog.close();else if(b.matches('[data-example]')||b.id==='load-example')sampleData();else if(b.matches('[data-clear]')){if(confirm('Clear this dataset from the current session?')){state.data=null;state.name='';state.question='';state.report={};state.plan={};slots[state.mode]=null;render()}}else if(b.id==='download-template')downloadTemplate();else if(b.id==='back-upload'||b.id==='change-file')resetUpload();else if(b.id==='import-data')commitImport();else if(b.dataset.question){state.question=b.dataset.question;render();document.querySelector('.answer')?.focus?.()}});
document.addEventListener('change',e=>{if(e.target.dataset.reportCheck){state.report[e.target.dataset.reportCheck]=e.target.checked;render()}else if(e.target.id==='report-source')updateFormatGuide();else if(e.target.matches('[data-map]')||e.target.id==='currency'||e.target.id==='value-kind')updatePreflight();else if(e.target.id==='chart-metric'){state.metric=e.target.value;render()}else if(e.target.id==='campaign-sort'){state.sort=e.target.value;render()}else if(e.target.id==='period'){state.days=e.target.value;render()}else if(e.target.id==='file-input')processFile(e.target.files[0])});
document.addEventListener('input',e=>{if(e.target.id==='default-channel')updatePreflight();else if(e.target.dataset.reportField){state.report[e.target.dataset.reportField]=e.target.value}else if(e.target.dataset.planField){state.plan[e.target.dataset.planField]=e.target.value}else if(e.target.id==='campaign-search'){const position=e.target.selectionStart;state.search=e.target.value;render();const input=$('#campaign-search');input.focus();input.setSelectionRange(position,position)}});
const drop=$('#dropzone');for(const type of ['dragenter','dragover'])drop.addEventListener(type,e=>{e.preventDefault();drop.classList.add('dragging')});for(const type of ['dragleave','drop'])drop.addEventListener(type,e=>{e.preventDefault();drop.classList.remove('dragging')});drop.addEventListener('drop',e=>processFile(e.dataTransfer.files[0]));
dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});
render();

